function fTestG(){TGI='';sheet('Test de grossesse','<label class="btn ghost" style="text-align:center">'+icon('fa-camera')+'Ajouter une photo du test (facultatif)<input type="file" id="ft_tgph" accept="image/*" capture="environment" hidden></label><img id="ft_tgim" alt="" style="display:none;width:100%;border-radius:12px;margin:8px 0">'+W()+'<p class="small">Quel est le résultat ?</p><div class="grid2"><button class="btn ghost" data-ft-tg="neg">Négatif</button><button class="btn" data-ft-tg="pos">Positif 💗</button></div><p class="xs muted">Le plus fiable : à partir du jour des règles attendues, avec la première urine du matin. Un résultat négatif tôt peut devenir positif quelques jours plus tard.</p>')}
